import { CommonModule } from '@angular/common';
import { Component, OnInit, inject, signal } from '@angular/core';
import { ActivatedRoute, RouterLink } from '@angular/router';
import { ORDER_STATUS_LABELS, OrderDetailResponse, OrderListResponse, PaginatedResponse, PAYMENT_LABELS } from '../../../core/models/models';
import { OrderService } from '../../../core/services/order.service';
import { ToastService } from '../../../core/services/toast.service';
import { AppIconComponent } from '../../../shared/components/icon/icon';
import { ProductImagePipe } from '../../../shared/pipes/product-image.pipe';
import { PRODUCT_IMAGE_FALLBACK } from '../../../core/utils/image';

@Component({selector:'app-orders',standalone:true,imports:[CommonModule,RouterLink,AppIconComponent,ProductImagePipe],template:`
<div class="bg-paper"><div class="site-container page-shell">
<header class="page-header"><p class="eyebrow">Tài khoản</p><h1 class="page-title">Đơn hàng của tôi</h1><p class="page-description">Theo dõi trạng thái, sản phẩm và giá trị từng đơn hàng.</p></header>
@if(created()){<div class="mb-6 flex items-center gap-3 rounded-xl border border-emerald-200 bg-emerald-50 p-4 text-sm text-emerald-800"><app-icon name="check" class="h-5 w-5 shrink-0"/>Đơn hàng #{{created()}} đã được tạo thành công.</div>}
@if(loading()){<div class="skeleton h-56 rounded-xl"></div>}@else if(result().items.length===0){<div class="rounded-xl border border-border bg-surface py-16 text-center"><span class="mx-auto flex h-14 w-14 items-center justify-center rounded-full bg-cream text-primary"><app-icon name="package" class="h-6 w-6"/></span><h2 class="mt-5 font-serif text-2xl font-semibold">Bạn chưa có đơn hàng nào</h2><a routerLink="/products" class="btn-primary mt-6">Bắt đầu mua sách</a></div>}@else{
<div class="divide-y divide-border overflow-hidden rounded-xl border border-border bg-surface">@for(o of result().items;track o.orderId){<article class="grid gap-4 p-5 transition-colors hover:bg-paper md:grid-cols-[160px_minmax(0,1fr)_170px_auto] md:items-center"><div><p class="text-xs uppercase tracking-wider text-muted">Mã đơn</p><p class="mt-1 font-serif text-lg font-semibold text-secondary">#{{o.orderId}}</p><p class="mt-1 text-xs text-muted">{{o.orderDate|date:'dd/MM/yyyy HH:mm'}}</p></div><div><span class="badge-secondary">{{statusLabel(o.status)}}</span><p class="mt-2 text-sm text-muted">{{o.itemCount}} sản phẩm · {{paymentLabel(o.paymentMethod)}}</p></div><p class="font-semibold tnum text-secondary md:text-right">{{o.totalAmount|currency:'VND':'symbol-narrow':'1.0-0'}}</p><button class="btn-secondary" (click)="open(o.orderId)">Chi tiết</button></article>}</div>
@if(result().totalPages>1){<div class="mt-10 flex items-center justify-center gap-2"><button class="btn-secondary" [disabled]="result().page<=1" (click)="load(result().page-1)">Trước</button><span class="px-4 py-2 text-sm text-body tnum">{{result().page}} / {{result().totalPages}}</span><button class="btn-secondary" [disabled]="result().page>=result().totalPages" (click)="load(result().page+1)">Sau</button></div>}
}
@if(detail()){<div class="fixed inset-0 z-[70] flex items-end justify-center bg-black/40 p-0 sm:items-center sm:p-6" (click)="detail.set(null)"><section class="max-h-[92vh] w-full max-w-2xl overflow-auto rounded-t-2xl bg-surface p-6 sm:rounded-2xl sm:p-8" (click)="$event.stopPropagation()"><div class="flex items-start justify-between gap-5"><div><p class="eyebrow">Chi tiết đơn hàng</p><h2 class="mt-2 font-serif text-3xl font-semibold">#{{detail()!.orderId}}</h2><p class="mt-1 text-sm text-muted">{{detail()!.orderDate|date:'dd/MM/yyyy HH:mm'}}</p></div><button class="btn-ghost" (click)="detail.set(null)">Đóng</button></div><div class="mt-6 grid gap-4 rounded-xl border border-border bg-cream p-5 sm:grid-cols-2"><div><p class="text-xs text-muted">Trạng thái</p><p class="mt-1 font-medium text-secondary">{{statusLabel(detail()!.status)}}</p></div><div><p class="text-xs text-muted">Thanh toán</p><p class="mt-1 font-medium text-secondary">{{paymentLabel(detail()!.paymentMethod)}}</p></div><div class="sm:col-span-2"><p class="text-xs text-muted">Giao đến</p><p class="mt-1 text-sm leading-6 text-body">{{detail()!.address||'Không có địa chỉ lưu'}}</p></div></div><div class="mt-6 divide-y divide-border border-y border-border">@for(i of detail()!.items;track i.productId){<div class="flex gap-4 py-4"><a [routerLink]="['/products',i.productId]" class="h-20 w-14 shrink-0 overflow-hidden rounded-md bg-cream p-1">@if(i.imageUrl){<img [src]="i.imageUrl | productImage" (error)="$any($event.target).src = fallbackImg" [alt]="i.productName" class="h-full w-full object-contain"/>}</a><div class="min-w-0 flex-1"><a [routerLink]="['/products',i.productId]" class="font-medium text-secondary transition-colors hover:text-primary">{{i.productName}}</a><p class="mt-1 text-xs text-muted">{{i.quantity}} × {{i.unitPrice|currency:'VND':'symbol-narrow':'1.0-0'}}</p></div><p class="text-sm font-semibold tnum">{{i.subTotal|currency:'VND':'symbol-narrow':'1.0-0'}}</p></div>}</div><div class="mt-5 flex items-center justify-between border-t border-border pt-5 text-lg font-semibold text-secondary"><span>Tổng cộng</span><span class="tnum">{{detail()!.totalAmount|currency:'VND':'symbol-narrow':'1.0-0'}}</span></div>@if(canCancel(detail()!)){<button class="btn-danger mt-6" (click)="cancel(detail()!.orderId)">Hủy đơn hàng</button>}</section></div>}
</div></div>`})
export class OrdersComponent implements OnInit{
  fallbackImg = PRODUCT_IMAGE_FALLBACK;
  private toast = inject(ToastService);
  private api=inject(OrderService);private route=inject(ActivatedRoute);loading=signal(true);created=signal<number|undefined>(undefined);result=signal<PaginatedResponse<OrderListResponse>>({items:[],total:0,page:1,pageSize:10,totalPages:0});detail=signal<OrderDetailResponse|null>(null);statusLabel=(s:any)=>ORDER_STATUS_LABELS[s as keyof typeof ORDER_STATUS_LABELS]||s;paymentLabel=(s:any)=>PAYMENT_LABELS[s as keyof typeof PAYMENT_LABELS]||s;
  ngOnInit(){this.created.set(Number(this.route.snapshot.queryParamMap.get('created'))||undefined);this.load();}
  load(page=1){this.loading.set(true);this.api.getOrders(page).subscribe({next:r=>{this.result.set(r);this.loading.set(false);},error:()=>this.loading.set(false)});}
  open(id:number){this.api.getOrderById(id).subscribe(o=>this.detail.set(o));}
  canCancel(o:OrderDetailResponse){return o.status==='cho_xac_nhan'||o.status==='da_xac_nhan';}
  cancel(id:number){if(!confirm('Bạn chắc chắn muốn hủy đơn hàng này?'))return;this.api.cancelOrder(id).subscribe({next:r=>{if(r.data)this.detail.set(r.data);this.load(this.result().page);this.toast.success('Đơn hàng #'+id+' đã được hủy.');},error:e=>this.toast.error(e.error?.message||'Không thể hủy đơn hàng.')});}
}